pub(in crate::cleanup_plan::replay::factored::canonical_shared) struct RetainedMemo<T> {
    memo: Memo<T>,
    refusal: Option<Diagnostic>,
    controls_paid: bool,
}
impl<T> RetainedMemo<T> {
    pub(in crate::cleanup_plan::replay::factored::canonical_shared) fn new() -> Self {
