                        + size_of::<Option<Diagnostic>>()
                        + size_of::<Diagnostic>()
                        + size_of::<Result<(), Diagnostic>>(),
                    "factored retained memo controls and failure receiving",
                ) {
                    self.memo.failed = true;
                    self.refusal = Some(error);
                    return;
                }
            }
            self.controls_paid = true;
        }
    }
